    cfg = load({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_only():
    with tempfile.TemporaryDirectory() as d:
        path = Path(d) / "cfg.toml"
        _mk_toml(path, {"x": 10, "y": 20})
        cfg = load({}, toml_path=str(path))
