    import tomli as tomllib
from typing import Any


class ConfigError(Exception):
    pass


def _coerce(value: str, typ: type) -> Any:
    if typ is int:
        return int(value)
    if typ is float:
        return float(value)
    if typ is bool:
        return value == "True"
    if typ is str:
        return value
    raise ValueError(f"cannot coerce to {typ.__name__}")


